-- Cria a tabela Subcategorias caso não exista (PostgreSQL).
-- Necessário quando o banco foi criado manualmente ou as migrations não foram aplicadas na ordem esperada.
-- Execute no banco usado pela API. A tabela Categorias deve existir.

DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'Subcategorias') THEN
        CREATE TABLE "Subcategorias" (
            "Id" integer GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
            "Nome" character varying(100) NOT NULL,
            "CategoriaId" integer NOT NULL,
            CONSTRAINT "FK_Subcategorias_Categorias_CategoriaId" 
                FOREIGN KEY ("CategoriaId") REFERENCES "Categorias"("Id") ON DELETE RESTRICT
        );
        CREATE INDEX "IX_Subcategorias_CategoriaId" ON "Subcategorias" ("CategoriaId");
    END IF;
EXCEPTION WHEN OTHERS THEN
    RAISE NOTICE 'Erro ao criar Subcategorias: %', SQLERRM;
END $$;
